"""Actions tab — renders an HTML actions page from the filesystem.

Displays an HTML file from ~/source/personal-assistant/. Refreshed
by the Assistant tab's refresh button, not independently.
"""

from __future__ import annotations

import tkinter as tk
from typing import Any

from personal_assistant.config import (
    BG_OUTPUT,
    FG_TEXT,
    FONT_BODY,
    PAD,
)

# Path to the actions HTML file
from personal_assistant.assistant_tab import ACTIONS_HTML, SPACING_CSS


class ActionsTab:
    """Actions tab — renders HTML from the filesystem."""

    def __init__(self, parent: tk.Frame) -> None:
        self._parent = parent
        self._html_frame: Any = None
        self._build()

    def _build(self) -> None:
        # Control bar with reload button
        controls = tk.Frame(self._parent, bg=BG_OUTPUT)
        controls.pack(fill=tk.X, padx=PAD, pady=(PAD, 0))

        tk.Button(
            controls,
            text="\U0001f504",
            command=self.refresh,
            bg="#4e4e4e",
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground="#5e5e5e",
            cursor="hand2",
            padx=4,
        ).pack(side=tk.RIGHT)

        try:
            from tkinterweb import HtmlFrame

            import webbrowser

            self._html_frame = HtmlFrame(
                self._parent,
                messages_enabled=False,
                dark_theme_enabled=True,
                on_link_click=lambda url: webbrowser.open(url),
            )
            self._html_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            self.refresh()
        except ImportError:
            fallback = tk.Text(
                self._parent,
                bg=BG_OUTPUT,
                fg=FG_TEXT,
                font=FONT_BODY,
                wrap=tk.WORD,
                state=tk.DISABLED,
                highlightthickness=0,
            )
            fallback.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            fallback.configure(state=tk.NORMAL)
            fallback.insert(
                "1.0",
                "tkinterweb not installed. Run: pip install tkinterweb[recommended]",
            )
            fallback.configure(state=tk.DISABLED)

    def refresh(self) -> None:
        """Reload the HTML file."""
        if self._html_frame is None:
            return
        if ACTIONS_HTML.exists():
            content = ACTIONS_HTML.read_text(encoding="utf-8")
            self._html_frame.load_html(content)
            self._html_frame.add_css(SPACING_CSS)
        else:
            self._html_frame.load_html(
                f"<html><body style='background:#252525;color:#ccc;"
                f"font-family:sans-serif;padding:20px'>"
                f"<p>No actions page found at:</p>"
                f"<code>{ACTIONS_HTML}</code>"
                f"</body></html>"
            )
